// GENERATED by cruftfree-codegen-flutter. DO NOT EDIT.
//
// A map basemap drawn from an installed offline package
// (`basemaps(offline(Site, key, "style.json"))`). The style document is a member
// of the installed copy; every address it names -- a source's `url`, `tiles` and
// `data`, the `glyphs` template and the `sprite` -- must be a path inside the
// package, and is rewritten to this adapter's `localUrl(path)`: a `file://`
// address under a directory of the app's private store holding exactly the
// copy's verified members, written there when the basemap is first shown and
// removed with the store whenever a session ends. A style naming any other
// address is refused whole; a text layer's fonts are written as literal names,
// so the engine never builds a glyph address from the data; and a template
// keeps only placeholders the engine fills with digits or those names, so no
// address the engine builds leaves the directory. Nothing of a package basemap
// reaches the network. The rule is the shared one, held to the shared tables by
// the app's package-sources test.

import 'dart:convert';
import 'dart:io';

import 'package:cruftfree_client/core/store.dart';

/// Why a package style was refused.
abstract final class CruftFreePackageStyleRefusal {
  static const String reference = 'reference';
  static const String font = 'font';
  static const String shape = 'shape';
}

/// A package style the rule refuses: [reason] says why.
class CruftFreePackageStyleRefused implements Exception {
  const CruftFreePackageStyleRefused(this.reason, this.message);

  final String reason;
  final String message;

  @override
  String toString() => 'CruftFreePackageStyleRefused($reason): $message';
}

/// A map's `offline(Package, key, "style")` basemap: switched to by [name] (the
/// package's name), drawn from the copy of [packageName] installed under [key]
/// (the catalogue key text), its style the member [style].
class CruftFreePackageBasemap {
  const CruftFreePackageBasemap({required this.name, required this.packageName, required this.key, required this.style});

  final String name;
  final String packageName;
  final String key;
  final String style;

  /// What the basemap is loaded for: another key loads it again.
  String get token => jsonEncode([name, packageName, key, style]);
}

/// What reads an app's installed packages: the app state's `cruftfree.ui` functions,
/// the one catalogue every client reads (`installedPackage`, `packageMember`).
class CruftFreePackageReader {
  const CruftFreePackageReader({required this.copy, required this.read});

  /// The copy of a package installed under a key -- its member paths, then what
  /// tells one installed copy from the next (its manifest and file slot) -- or
  /// `null`. A positional record: the glue a view writes for it stays on one line.
  final Future<(List<String>, String)?> Function(String packageName, String key) copy;

  /// The bytes (base64) of one member of that copy, or `null`.
  final Future<String?> Function(String packageName, String key, String path) read;
}

const int _maxReference = 1024;
const Set<String> _forbiddenPathCharacters = {':', r'\', '?', '#', '%'};
const Set<String> _templatePlaceholders = {'fontstack', 'prefix', 'quadkey', 'range', 'ratio', 'x', 'y', 'z'};
final RegExp _placeholder = RegExp(r'\{([a-z]+)\}');
const String _spriteIndexSuffix = '.json';
const String _literalOperator = 'literal';

/// The directory of the store a package basemap's members are written under.
const String _exportedRoot = 'package-maps';

/// The file a written copy's directory holds once every member is in it.
const String _completeMarker = '.complete';

bool _hasControlCharacter(String text) => text.runes.any((code) => code < 0x20 || code == 0x7f);

/// [reference] when it is a path inside a package, else `null`.
String? cruftfreePackageLocalPath(String reference) {
  if (reference.isEmpty || reference.length > _maxReference || reference.startsWith('/')) {
    return null;
  }
  if (_hasControlCharacter(reference) || reference.split('').any(_forbiddenPathCharacters.contains)) {
    return null;
  }
  if (reference.split('/').any((segment) => segment.isEmpty || segment == '.' || segment == '..')) {
    return null;
  }
  return reference;
}

String? _templatePath(String reference) {
  final path = cruftfreePackageLocalPath(reference);
  if (path == null) {
    return null;
  }
  final literal = path.replaceAll(_placeholder, '');
  if (literal.contains('{') || literal.contains('}')) {
    return null;
  }
  if (_placeholder.allMatches(path).any((match) => !_templatePlaceholders.contains(match.group(1)))) {
    return null;
  }
  return path;
}

String _resolved(Object? reference, Set<String> members, String Function(String path) localUrl, {String suffix = ''}) {
  if (reference is! String) {
    throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.reference, 'A package style address $reference is no text.');
  }
  final path = _templatePath(reference);
  if (path == null) {
    throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.reference, "The package style address '$reference' is no path inside the package.");
  }
  if (!_placeholder.hasMatch(path) && !members.contains('$path$suffix')) {
    throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.reference, "The package style address '$reference' names no member of the package.");
  }
  return localUrl(path);
}

bool _safeFontName(Object? name) {
  if (name is! String || name.isEmpty || name == '.' || name == '..') {
    return false;
  }
  return !_hasControlCharacter(name) && !name.contains('/') && !name.contains(r'\') && !name.contains('%');
}

void _literalFonts(Object? layers) {
  if (layers is! List) {
    throw const CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.shape, "A package style's layers are no list.");
  }
  for (final layer in layers) {
    final layout = layer is Map ? layer['layout'] : null;
    if (layout is! Map || !layout.containsKey('text-font')) {
      continue;
    }
    Object? fonts = layout['text-font'];
    if (fonts is List && fonts.length == 2 && fonts[0] == _literalOperator) {
      fonts = fonts[1];
    }
    if (fonts is! List || fonts.isEmpty || !fonts.every(_safeFontName)) {
      throw const CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.font, "A package style layer's text-font is no list of plain font names.");
    }
    layout['text-font'] = [_literalOperator, List<Object?>.of(fonts)];
  }
}

Object? _rewriteSprite(Object? sprite, Set<String> members, String Function(String path) localUrl) {
  if (sprite is! List) {
    return _resolved(sprite, members, localUrl, suffix: _spriteIndexSuffix);
  }
  final rewritten = <Object?>[];
  for (final entry in sprite) {
    if (entry is! Map || entry['id'] is! String) {
      throw const CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.shape, "A package style's sprite entry is no {id, url}.");
    }
    rewritten.add({...entry, 'url': _resolved(entry['url'], members, localUrl, suffix: _spriteIndexSuffix)});
  }
  return rewritten;
}

Map<String, Object?> _rewriteSource(String name, Object? source, Set<String> members, String Function(String path) localUrl) {
  if (source is! Map) {
    throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.shape, "The package style source '$name' is no object.");
  }
  final rewritten = <String, Object?>{for (final MapEntry(:key, :value) in source.entries) '$key': value};
  for (final key in const ['url', 'data']) {
    if (key == 'data' && source[key] is! String) {
      continue;
    }
    if (source.containsKey(key)) {
      rewritten[key] = _resolved(source[key], members, localUrl);
    }
  }
  if (source.containsKey('urls')) {
    throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.reference, "The package style source '$name' names video addresses.");
  }
  if (source.containsKey('tiles')) {
    final tiles = source['tiles'];
    if (tiles is! List || tiles.isEmpty) {
      throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.shape, "The package style source '$name' has no list of tiles.");
    }
    rewritten['tiles'] = [for (final tile in tiles) _resolved(tile, members, localUrl)];
  }
  return rewritten;
}

/// The package style [document] with every address rewritten through [localUrl];
/// throws [CruftFreePackageStyleRefused] for a style that reaches outside the package.
/// [document] is not changed.
Map<String, Object?> cruftfreePackageStyle(Object? document, Set<String> members, String Function(String path) localUrl) {
  if (document is! Map || document['sources'] is! Map) {
    throw const CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.shape, 'A package style is no object with sources.');
  }
  final style = jsonDecode(jsonEncode(document)) as Map<String, Object?>;
  if (style.containsKey('layers')) {
    _literalFonts(style['layers']);
  }
  final sources = document['sources'] as Map;
  style['sources'] = <String, Object?>{for (final MapEntry(:key, :value) in sources.entries) '$key': _rewriteSource('$key', value, members, localUrl)};
  if (document.containsKey('glyphs')) {
    style['glyphs'] = _resolved(document['glyphs'], members, localUrl);
  }
  if (document.containsKey('sprite')) {
    style['sprite'] = _rewriteSprite(document['sprite'], members, localUrl);
  }
  return style;
}

/// The `file://` address of the package path [path] under [directory], or `null`
/// -- it resolves nothing -- when [path] is no path inside a package.
String? cruftfreePackageFileUrl(Directory directory, String path) {
  final local = _templatePath(path);
  return local == null ? null : _fileAddress(directory, local);
}

/// The `file://` address of the package path [path] under [directory]: the
/// directory's own file URL, then each segment of [path] percent-encoded around
/// its placeholders, which the map engine fills (and encodes) itself.
String _fileAddress(Directory directory, String path) {
  final segments = [for (final segment in path.split('/')) segment.splitMapJoin(_placeholder, onMatch: (match) => match.group(0)!, onNonMatch: Uri.encodeComponent)];
  return '${directory.uri}${segments.join('/')}';
}

/// A package basemap loaded: its style document, every address a file of
/// [directory].
class CruftFreeLoadedPackageBasemap {
  const CruftFreeLoadedPackageBasemap(this.document, this.directory);

  final Map<String, Object?> document;
  final Directory directory;
}

/// Writes the copy of [basemap] that [reader] reads into its own directory of
/// [store] -- once per installed copy: a copy written before is used as it is --
/// and answers its style document rewritten onto those files. Throws when no
/// copy is installed, the style is no member, a member cannot be read, or the
/// rule refuses the style.
Future<CruftFreeLoadedPackageBasemap> cruftfreeLoadPackageBasemap(CruftFreePackageReader reader, CruftFreePackageBasemap basemap, DeviceStore store) async {
  final copied = await reader.copy(basemap.packageName, basemap.key);
  if (copied == null) {
    throw StateError('The basemap ${basemap.name} draws from a package with no installed copy.');
  }
  final (members, version) = copied;
  final stylePath = cruftfreePackageLocalPath(basemap.style);
  if (stylePath == null || !members.contains(stylePath)) {
    throw CruftFreePackageStyleRefused(CruftFreePackageStyleRefusal.reference, "The basemap ${basemap.name}'s style '${basemap.style}' is no member of its package.");
  }
  final listed = [...members]..sort();
  // One directory per package and key, holding the one copy last written: a copy
  // installed since replaces it.
  final group = '$_exportedRoot/${jsonEncode([basemap.packageName, basemap.key])}';
  final directory = store.exportDirectory(group, jsonEncode([version, listed]));
  if (!await File('${directory.path}/$_completeMarker').exists()) {
    await _writeCopy(reader, basemap, listed, directory);
  }
  final style = await File('${directory.path}/$stylePath').readAsString();
  final document = cruftfreePackageStyle(jsonDecode(style), listed.toSet(), (path) => _fileAddress(directory, path));
  return CruftFreeLoadedPackageBasemap(document, directory);
}

Future<void> _writeCopy(CruftFreePackageReader reader, CruftFreePackageBasemap basemap, List<String> members, Directory directory) async {
  if (await directory.parent.exists()) {
    await directory.parent.delete(recursive: true);
  }
  for (final member in members) {
    final path = cruftfreePackageLocalPath(member);
    final bytes = path == null ? null : await reader.read(basemap.packageName, basemap.key, path);
    if (path == null || bytes == null) {
      await directory.delete(recursive: true);
      throw StateError("The installed copy of ${basemap.packageName} holds no member '$member' the map can read.");
    }
    final file = File('${directory.path}/$path');
    await file.parent.create(recursive: true);
    await file.writeAsBytes(base64Decode(bytes), flush: true);
  }
  await File('${directory.path}/$_completeMarker').writeAsString('', flush: true);
}
